import torch
import torch.nn as nn


class FunctorialStateLift(nn.Module):
    def __init__(self, dim: int = 8):
        super().__init__()
        self.dim = dim

    def lift_state(self, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Lossless lift of the attention key/value history into a recurrent
        # state matrix: S = sum_t k_t v_t^T = K^T V. Reading the state with a
        # query Q reproduces the (linear) attention output Q S, so no temporal
        # correlation information is discarded.
        B, T, D = K.shape
        if V.shape != K.shape:
            raise ValueError(
                f"K and V must have the same shape, got {K.shape} vs {V.shape}"
            )
        return torch.einsum("btd,bte->bde", K, V)

