import torch
import torch.nn as nn


class RecurrentStateIsomorphism(nn.Module):
    def __init__(self, dim: int = 8):
        super().__init__()
        self.dim = dim

    def _check_inputs(self, K: torch.Tensor, V: torch.Tensor):
        if K.dim() == 2:
            K = K.unsqueeze(0)
        if V.dim() == 2:
            V = V.unsqueeze(0)
        if K.dim() != 3 or V.dim() != 3:
            raise ValueError(f"expected (B, T, D) tensors, got {K.shape} / {V.shape}")
        if K.shape != V.shape:
            raise ValueError(
                f"K and V must have identical shapes, got {K.shape} vs {V.shape}"
            )
        if K.shape[2] != self.dim:
            raise ValueError(f"expected trailing dim {self.dim}, got {K.shape[2]}")
        return K, V

    def forward(self, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Convenience passthrough so the module is callable directly.
        return self.lift_state(K, V)

    def lift_state(self, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Exact associative lift: S = sum_t k_t (x) v_t^T == K^T @ V.
        #
        # For any query set Q, the recurrent read Q @ S reproduces the linear
        # attention output over the full history exactly:
        #
        #     Q @ S = Q @ (K^T V) = sum_t (q . k_t) v_t
        #
        # Nothing about (K, V) is destroyed: the sequence of outer products is
        # associatively folded into a single (D, D) matrix, and the state stays
        # incrementally composable (S' = S + k v^T).
        K, V = self._check_inputs(K, V)
        return torch.bmm(K.transpose(1, 2), V)

    def read_state(self, state: torch.Tensor, Q: torch.Tensor) -> torch.Tensor:
        # Recurrent read: linear attention over the folded history.
        if state.dim() == 2:
            state = state.unsqueeze(0)
        if Q.dim() == 2:
            Q = Q.unsqueeze(0)
        return Q @ state

    def fold(self, state: torch.Tensor, k: torch.Tensor, v: torch.Tensor) -> torch.Tensor:
        # Incremental composition rule for the lifted state: S' = S + k v^T.
        if state.dim() == 2:
            state = state.unsqueeze(0)
        if k.dim() == 2:
            k = k.unsqueeze(0)
        if v.dim() == 2:
            v = v.unsqueeze(0)
        return state + torch.matmul(k.transpose(1, 2), v)
